WITH lines AS (SELECT id, created_at, coupon_codes, line.product_id, line.qty, line.price, line.promo FROM carts LATERAL VIEW OUTER EXPLODE(items) x AS line) SELECT *, RANK() OVER (ORDER BY qty DESC NULLS LAST) AS qty_rank, DENSE_RANK() OVER (PARTITION BY promo ORDER BY qty DESC NULLS FIRST) AS qty_dense_rank, ROUND(price / SUM(price) OVER (PARTITION BY promo), 4) AS price_share FROM lines
